CREATE INDEX IF NOT EXISTS idx_tprm_processing_failures ON tprm_monitoring_processing_attempts (workspace_id,status,completed_at DESC);
CREATE INDEX IF NOT EXISTS idx_tprm_connector_runs_health ON tprm_monitoring_connector_runs (workspace_id,connector_id,completed_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS idx_tprm_reassessment_queue_work ON tprm_reassessment_queue (status,next_attempt_at,priority,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tprm_recommendation_draft_open_cycle ON tprm_recommendation_drafts (workspace_id,supplier_id,cycle_id) WHERE status NOT IN ('issued','withdrawn');
CREATE INDEX IF NOT EXISTS idx_tprm_recommendation_drafts_review ON tprm_recommendation_drafts (workspace_id,status,reviewer_id,updated_at);
CREATE INDEX IF NOT EXISTS idx_tprm_recommendation_revisions_draft ON tprm_recommendation_draft_revisions (draft_id,revision_number DESC);
CREATE INDEX IF NOT EXISTS idx_tprm_recommendation_draft_events ON tprm_recommendation_draft_events (draft_id,occurred_at,id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tprm_conditions_workspace_supplier_cycle_id ON tprm_conditions (workspace_id,supplier_id,cycle_id,id);
CREATE INDEX IF NOT EXISTS idx_tprm_condition_events_condition ON tprm_condition_events (workspace_id,condition_id,occurred_at,id);
CREATE INDEX IF NOT EXISTS idx_tprm_condition_evidence_condition ON tprm_condition_evidence_links (workspace_id,condition_id,uploaded_at,id);
CREATE INDEX IF NOT EXISTS idx_tprm_module_closure_retention ON tprm_module_closure_records (workspace_id,retention_until,legal_hold);
CREATE INDEX IF NOT EXISTS idx_tprm_webhook_ingress_bucket_retention ON tprm_webhook_ingress_buckets (updated_at);
CREATE INDEX IF NOT EXISTS idx_tprm_review_schedule_closures_supplier ON tprm_review_schedule_closures (workspace_id,supplier_id,closed_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_requirements_framework_id ON requirements (framework_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_control_instances_workspace_requirement_id ON control_instances (workspace_id,requirement_id,id);
CREATE INDEX IF NOT EXISTS idx_framework_catalog_releases_current ON framework_catalog_releases (framework_code, is_current);
CREATE UNIQUE INDEX IF NOT EXISTS uq_evidence_ai_indexes_active_identity ON evidence_ai_indexes (workspace_id,evidence_id,source_sha256,pipeline_key) WHERE status IN ('queued','processing','ready');
CREATE INDEX IF NOT EXISTS idx_evidence_ai_indexes_work ON evidence_ai_indexes (status,lease_expires_at,created_at);
CREATE INDEX IF NOT EXISTS idx_evidence_ai_indexes_workspace_ready ON evidence_ai_indexes (workspace_id,status,pipeline_key,evidence_id);
CREATE INDEX IF NOT EXISTS idx_evidence_ai_indexes_evidence ON evidence_ai_indexes (workspace_id,evidence_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_evidence_ai_chunks_workspace_index ON evidence_ai_chunks (workspace_id,index_id,ordinal);
CREATE INDEX IF NOT EXISTS idx_client_requests_released ON client_requests (workspace_id,released_at,assignee_id,status);
CREATE INDEX IF NOT EXISTS idx_notification_outbox_ready ON notification_outbox (status,available_at);
CREATE INDEX IF NOT EXISTS idx_assessment_review_source ON assessment_review_events (workspace_id,requirement_id,id);
CREATE INDEX IF NOT EXISTS idx_audsamp_audit ON audit_samples (audit_id);
CREATE INDEX IF NOT EXISTS idx_risk_assessment_records_ws ON risk_assessment_records (workspace_id, performed_on);
CREATE INDEX IF NOT EXISTS idx_context_issues_ws ON context_issues (workspace_id);
CREATE INDEX IF NOT EXISTS idx_risks_ws_system ON risks (workspace_id, management_system);
CREATE INDEX IF NOT EXISTS idx_risk_methodologies_active ON risk_methodologies (workspace_id, management_system, is_active);

CREATE INDEX IF NOT EXISTS search_index_search_vector_idx ON search_index USING gin (search_vector);
CREATE INDEX IF NOT EXISTS search_index_entity_idx ON search_index (workspace_id, entity_type, entity_id);

