CREATE OR REPLACE FUNCTION trg_supplier_decision_governed_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF (
     NEW.idempotency_nonce IS NOT NULL
     OR NEW.request_fingerprint IS NOT NULL
     OR NEW.expected_current_decision_id IS NOT NULL
     OR NEW.supersedes_id IS NOT NULL
   )
   AND (
     length(COALESCE(NEW.idempotency_nonce,''))<32
     OR length(NEW.idempotency_nonce)>128
     OR NEW.idempotency_nonce<>trim(NEW.idempotency_nonce)
     OR length(COALESCE(NEW.request_fingerprint,''))<>64
     OR COALESCE(NEW.request_fingerprint,'') ~ '[^0-9a-f]'
     OR NEW.expected_current_decision_id IS DISTINCT FROM NEW.supersedes_id
     OR (
       NEW.supersedes_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM supplier_decisions prior
          WHERE prior.id=NEW.supersedes_id
            AND prior.workspace_id=NEW.workspace_id
            AND prior.supplier_id=NEW.supplier_id
       )
     )
   )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'invalid governed supplier decision concurrency metadata';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_supplier_decision_governed_insert BEFORE INSERT ON supplier_decisions
  FOR EACH ROW EXECUTE FUNCTION trg_supplier_decision_governed_insert_fn();

CREATE OR REPLACE TRIGGER trg_supplier_decision_concurrency_immutable BEFORE UPDATE OF idempotency_nonce, request_fingerprint, expected_current_decision_id, supersedes_id ON supplier_decisions
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('supplier decision concurrency metadata is immutable');

CREATE OR REPLACE TRIGGER trg_supplier_contract_agreement_complete BEFORE UPDATE OF status ON supplier_contract_reviews
  FOR EACH ROW
  WHEN (NEW.status='complete' AND (
    trim(COALESCE(NEW.agreement_reference,''))=''
    OR NEW.agreement_reference<>trim(NEW.agreement_reference)
    OR length(COALESCE(NEW.agreement_date,''))!=10
    OR COALESCE(NEW.agreement_date,'') !~ '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$'
    OR sqlite_date_ymd(NEW.agreement_date) IS DISTINCT FROM NEW.agreement_date
  ))
  EXECUTE FUNCTION sqlite_raise_abort('completed supplier contract review requires an agreement reference and valid ISO agreement date');

CREATE OR REPLACE FUNCTION trg_doc_approver_workspace_guard_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM generated_docs d
    JOIN doc_versions dv
      ON dv.id = NEW.version_id
     AND dv.document_id = NEW.document_id
     AND dv.workspace_id = NEW.workspace_id
    JOIN workspaces w
      ON w.id = NEW.workspace_id
     AND d.workspace_id = w.id
     AND d.id = NEW.document_id
    JOIN users u
      ON u.id = NEW.user_id
     AND u.active = 1
    LEFT JOIN workspace_members wm
      ON wm.workspace_id = NEW.workspace_id
     AND wm.user_id = u.id
    WHERE (u.user_type = 'firm' AND u.firm_id = w.firm_id)
       OR (u.user_type = 'client' AND wm.user_id IS NOT NULL)
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'internal document approver is outside the workspace boundary';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_doc_approver_workspace_guard BEFORE INSERT ON doc_approvers
  FOR EACH ROW EXECUTE FUNCTION trg_doc_approver_workspace_guard_fn();

CREATE OR REPLACE TRIGGER trg_doc_internal_rejection_reason_insert BEFORE INSERT ON doc_approvers
  FOR EACH ROW
  WHEN (NEW.decision = 'rejected' AND trim(COALESCE(NEW.decision_reason, '')) = '')
