CREATE OR REPLACE FUNCTION trg_nc_evidence_link_no_delete_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF EXISTS (SELECT 1 FROM workspaces WHERE id=OLD.workspace_id)
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'nonconformity evidence lineage is immutable';
  END IF;
  RETURN OLD;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_nc_evidence_link_no_delete BEFORE DELETE ON nonconformity_evidence_links
  FOR EACH ROW EXECUTE FUNCTION trg_nc_evidence_link_no_delete_fn();

CREATE OR REPLACE FUNCTION trg_certification_finding_lineage_immutable_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF (
    EXISTS (
      SELECT 1 FROM cert_cycle_events ce
      WHERE ce.workspace_id=OLD.workspace_id
        AND ce.event_type IN ('stage_1','stage_2')
        AND OLD.source_ref='cert_cycle_event:' || ce.id
        AND lower(COALESCE(OLD.source,''))='external_audit'
    )
    AND (
      NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
      OR lower(COALESCE(NEW.source,'')) IS DISTINCT FROM lower(COALESCE(OLD.source,''))
      OR NEW.source_ref IS DISTINCT FROM OLD.source_ref
    )
  ) OR (
    NOT EXISTS (
      SELECT 1 FROM cert_cycle_events ce
      WHERE ce.workspace_id=OLD.workspace_id
        AND ce.event_type IN ('stage_1','stage_2')
        AND OLD.source_ref='cert_cycle_event:' || ce.id
        AND lower(COALESCE(OLD.source,''))='external_audit'
    )
    AND EXISTS (
      SELECT 1 FROM cert_cycle_events ce
      WHERE ce.workspace_id=NEW.workspace_id
        AND ce.event_type IN ('stage_1','stage_2')
        AND NEW.source_ref='cert_cycle_event:' || ce.id
        AND lower(COALESCE(NEW.source,''))='external_audit'
    )
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'certification finding lineage is immutable';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_certification_finding_lineage_immutable BEFORE UPDATE OF workspace_id, source, source_ref ON nonconformities
  FOR EACH ROW EXECUTE FUNCTION trg_certification_finding_lineage_immutable_fn();

CREATE OR REPLACE FUNCTION trg_certification_finding_no_delete_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF lower(COALESCE(OLD.source,''))='external_audit'
   AND EXISTS (
     SELECT 1 FROM cert_cycle_events ce
     WHERE ce.workspace_id=OLD.workspace_id
       AND ce.event_type IN ('stage_1','stage_2')
       AND OLD.source_ref='cert_cycle_event:' || ce.id
   )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'certification findings are retained audit history';
  END IF;
  RETURN OLD;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_certification_finding_no_delete BEFORE DELETE ON nonconformities
  FOR EACH ROW EXECUTE FUNCTION trg_certification_finding_no_delete_fn();

CREATE OR REPLACE FUNCTION trg_certification_event_with_findings_no_delete_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF OLD.event_type IN ('stage_1','stage_2')
   AND EXISTS (
     SELECT 1 FROM nonconformities n
     WHERE n.workspace_id=OLD.workspace_id
       AND lower(COALESCE(n.source,''))='external_audit'
       AND n.source_ref='cert_cycle_event:' || OLD.id
   )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'certification events with retained findings cannot be deleted';
  END IF;
  RETURN OLD;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_certification_event_with_findings_no_delete BEFORE DELETE ON cert_cycle_events
  FOR EACH ROW EXECUTE FUNCTION trg_certification_event_with_findings_no_delete_fn();

CREATE OR REPLACE FUNCTION trg_certification_finding_closure_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF lower(COALESCE(NEW.status,'')) IN ('closed','verified')
   AND lower(COALESCE(NEW.source,''))='external_audit'
   AND EXISTS (
     SELECT 1 FROM cert_cycle_events ce
     WHERE ce.workspace_id=NEW.workspace_id
       AND ce.event_type IN ('stage_1','stage_2')
       AND NEW.source_ref='cert_cycle_event:' || ce.id
   )
   AND (
     trim(COALESCE(NEW.corrective_action,''))=''
     OR trim(COALESCE(NEW.effectiveness_check,''))=''
     OR (lower(COALESCE(NEW.severity,'')) IN ('major','minor') AND trim(COALESCE(NEW.root_cause,''))='')
     OR NOT EXISTS (
       SELECT 1 FROM nonconformity_evidence_links l
       WHERE l.workspace_id=NEW.workspace_id
         AND l.nonconformity_id=NEW.id
         AND l.evidence_role='validation'
     )
   )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'certification finding closure requires CAPA and validation evidence';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_certification_finding_closure_insert BEFORE INSERT ON nonconformities
  FOR EACH ROW EXECUTE FUNCTION trg_certification_finding_closure_insert_fn();

CREATE OR REPLACE FUNCTION trg_certification_finding_closure_update_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF lower(COALESCE(NEW.status,'')) IN ('closed','verified')
   AND lower(COALESCE(NEW.source,''))='external_audit'
   AND EXISTS (
     SELECT 1 FROM cert_cycle_events ce
     WHERE ce.workspace_id=NEW.workspace_id
       AND ce.event_type IN ('stage_1','stage_2')
       AND NEW.source_ref='cert_cycle_event:' || ce.id
   )
   AND (
     trim(COALESCE(NEW.corrective_action,''))=''
     OR trim(COALESCE(NEW.effectiveness_check,''))=''
     OR (lower(COALESCE(NEW.severity,'')) IN ('major','minor') AND trim(COALESCE(NEW.root_cause,''))='')
     OR NOT EXISTS (
       SELECT 1 FROM nonconformity_evidence_links l
       WHERE l.workspace_id=NEW.workspace_id
         AND l.nonconformity_id=NEW.id
         AND l.evidence_role='validation'
     )
   )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'certification finding closure requires CAPA and validation evidence';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_certification_finding_closure_update BEFORE UPDATE OF status, severity, root_cause, corrective_action, effectiveness_check, workspace_id, source, source_ref ON nonconformities
  FOR EACH ROW EXECUTE FUNCTION trg_certification_finding_closure_update_fn();

CREATE OR REPLACE TRIGGER trg_supplier_contract_agreement_complete_insert BEFORE INSERT ON supplier_contract_reviews
  FOR EACH ROW
  WHEN (NEW.status='complete' AND (
    trim(COALESCE(NEW.agreement_reference,''))=''
    OR NEW.agreement_reference<>trim(NEW.agreement_reference)
    OR length(COALESCE(NEW.agreement_date,''))!=10
    OR COALESCE(NEW.agreement_date,'') !~ '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$'
    OR sqlite_date_ymd(NEW.agreement_date) IS DISTINCT FROM NEW.agreement_date
  ))
  EXECUTE FUNCTION sqlite_raise_abort('completed supplier contract review requires an agreement reference and valid ISO agreement date');

