CREATE OR REPLACE FUNCTION trg_tprm_recommendation_actor_governance_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM workspaces w
    JOIN users author ON author.id=NEW.issued_by
    JOIN users reviewer ON reviewer.id=NEW.quality_reviewed_by
    WHERE w.id=NEW.workspace_id
      AND author.user_type='firm' AND reviewer.user_type='firm'
      AND author.firm_id=w.firm_id AND reviewer.firm_id=w.firm_id
      AND author.active=1 AND reviewer.active=1
      AND author.id<>reviewer.id
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM recommendation requires distinct active firm author and quality reviewer';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_actor_governance BEFORE INSERT ON tprm_recommendations
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_actor_governance_fn();

CREATE OR REPLACE FUNCTION trg_tprm_recommendation_lineage_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF (
    (NEW.supersedes_id IS NULL AND NEW.version<>1)
    OR (NEW.supersedes_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM tprm_recommendations prior
      WHERE prior.id=NEW.supersedes_id
        AND prior.workspace_id=NEW.workspace_id
        AND prior.supplier_id=NEW.supplier_id
        AND prior.cycle_id=NEW.cycle_id
        AND NEW.version=prior.version+1
    ))
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'invalid TPRM recommendation version lineage';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_lineage BEFORE INSERT ON tprm_recommendations
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_lineage_fn();

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_no_update BEFORE UPDATE ON tprm_recommendations
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('issued TPRM recommendations are immutable; issue a successor version');

