CREATE OR REPLACE FUNCTION trg_tprm_client_decision_recommendation_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM tprm_recommendations r
    WHERE r.id=NEW.recommendation_id
      AND r.workspace_id=NEW.workspace_id
      AND r.supplier_id=NEW.supplier_id
      AND r.cycle_id=NEW.cycle_id
      AND r.version=NEW.recommendation_version
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'client decision must reference the exact recommendation version';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_client_decision_recommendation BEFORE INSERT ON tprm_client_decisions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_client_decision_recommendation_fn();

CREATE OR REPLACE FUNCTION trg_tprm_client_decision_divergence_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.diverges_from_recommendation IS DISTINCT FROM (
    SELECT CASE
      WHEN (r.outcome='recommend_onboard' AND NEW.decision='onboard')
        OR (r.outcome='recommend_with_conditions' AND NEW.decision='onboard_with_conditions')
        OR (r.outcome='do_not_recommend' AND NEW.decision='do_not_onboard')
        OR (r.outcome='insufficient_information' AND NEW.decision='defer_request_information')
      THEN 0 ELSE 1 END
    FROM tprm_recommendations r WHERE r.id=NEW.recommendation_id
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'client decision divergence flag does not match the recommendation';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_client_decision_divergence BEFORE INSERT ON tprm_client_decisions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_client_decision_divergence_fn();

CREATE OR REPLACE TRIGGER trg_tprm_client_decision_override_acceptance BEFORE INSERT ON tprm_client_decisions
  FOR EACH ROW
  WHEN (NEW.diverges_from_recommendation=1
   AND NEW.decision IN ('onboard','onboard_with_conditions')
   AND (
     length(trim(COALESCE(NEW.override_rationale,'')))<10
     OR length(trim(COALESCE(NEW.risk_acceptance_statement,'')))<10
     OR NEW.risk_acceptance_expires_at IS NULL
   ))
  EXECUTE FUNCTION sqlite_raise_abort('divergent onboarding requires explicit client override rationale and expiring risk acceptance');

