CREATE OR REPLACE FUNCTION trg_tprm_connector_actor_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM users u JOIN workspaces w ON w.id=NEW.workspace_id
    WHERE u.id=NEW.created_by AND u.user_type='firm' AND u.active=1 AND u.firm_id=w.firm_id
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM connector creator must be an active consultancy user for this workspace';
  END IF;
  RETURN NEW;
END;
$fn$;
