  FOR EACH ROW EXECUTE FUNCTION trg_tprm_connector_actor_insert_fn();

CREATE OR REPLACE FUNCTION trg_tprm_connector_active_module_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.status='active' AND NOT EXISTS (
    SELECT 1 FROM tprm_modules m
    WHERE m.workspace_id=NEW.workspace_id AND m.id=NEW.module_id AND m.status='active'
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM connector cannot be active unless its module is active';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_connector_active_module_insert BEFORE INSERT ON tprm_monitoring_connectors
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_connector_active_module_insert_fn();

