CREATE OR REPLACE FUNCTION trg_tprm_recommendation_draft_actor_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM workspaces w JOIN users u ON u.id=NEW.author_id
    WHERE w.id=NEW.workspace_id AND u.user_type='firm' AND u.active=1 AND u.firm_id=w.firm_id
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM recommendation draft author must be an active consultancy user';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_actor_insert BEFORE INSERT ON tprm_recommendation_drafts
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_draft_actor_insert_fn();

CREATE OR REPLACE FUNCTION trg_tprm_recommendation_draft_reviewer_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.reviewer_id IS NOT NULL AND (
    NEW.reviewer_id=NEW.author_id OR NOT EXISTS (
      SELECT 1 FROM workspaces w JOIN users u ON u.id=NEW.reviewer_id
      WHERE w.id=NEW.workspace_id AND u.user_type='firm' AND u.active=1 AND u.firm_id=w.firm_id
    )
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM recommendation reviewer must be a distinct active consultancy user';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_reviewer BEFORE UPDATE OF reviewer_id ON tprm_recommendation_drafts
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_draft_reviewer_fn();

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_identity BEFORE UPDATE OF workspace_id, supplier_id, cycle_id, author_id, created_at ON tprm_recommendation_drafts
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM recommendation draft identity is immutable');

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_status BEFORE UPDATE OF status ON tprm_recommendation_drafts
  FOR EACH ROW
  WHEN (NOT (
    (OLD.status IN ('draft','changes_requested') AND NEW.status='in_review')
    OR (OLD.status='in_review' AND NEW.status IN ('changes_requested','issued','withdrawn'))
    OR (OLD.status IN ('draft','changes_requested') AND NEW.status='withdrawn')
  ))
  EXECUTE FUNCTION sqlite_raise_abort('invalid TPRM recommendation draft status transition');

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_no_delete BEFORE DELETE ON tprm_recommendation_drafts
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM recommendation drafts cannot be deleted');

CREATE OR REPLACE FUNCTION trg_tprm_recommendation_revision_scope_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM tprm_recommendation_drafts d
    JOIN workspaces w ON w.id=d.workspace_id
    JOIN users u ON u.id=NEW.created_by
    WHERE d.id=NEW.draft_id AND d.workspace_id=NEW.workspace_id
      AND d.supplier_id=NEW.supplier_id AND d.cycle_id=NEW.cycle_id
      AND d.status IN ('draft','changes_requested')
      AND u.user_type='firm' AND u.active=1 AND u.firm_id=w.firm_id
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM recommendation revision is outside an editable consultancy draft';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_revision_scope BEFORE INSERT ON tprm_recommendation_draft_revisions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_revision_scope_fn();

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_revision_no_update BEFORE UPDATE ON tprm_recommendation_draft_revisions
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM recommendation draft revisions are immutable');

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_revision_no_delete BEFORE DELETE ON tprm_recommendation_draft_revisions
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM recommendation draft revisions cannot be deleted');

CREATE OR REPLACE FUNCTION trg_tprm_recommendation_draft_event_actor_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM workspaces w JOIN users u ON u.id=NEW.actor_id
    WHERE w.id=NEW.workspace_id AND u.user_type='firm' AND u.active=1 AND u.firm_id=w.firm_id
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM recommendation draft event requires an active consultancy actor';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_event_actor BEFORE INSERT ON tprm_recommendation_draft_events
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_draft_event_actor_fn();

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_event_no_update BEFORE UPDATE ON tprm_recommendation_draft_events
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM recommendation draft events are immutable');

CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_event_no_delete BEFORE DELETE ON tprm_recommendation_draft_events
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM recommendation draft events cannot be deleted');

CREATE OR REPLACE FUNCTION trg_tprm_condition_event_scope_and_version_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM tprm_conditions c
    WHERE c.id=NEW.condition_id AND c.workspace_id=NEW.workspace_id
      AND c.supplier_id=NEW.supplier_id AND c.cycle_id=NEW.cycle_id
      AND c.status=NEW.from_status AND c.row_version=NEW.expected_row_version
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition event is stale or outside its tenant and cycle';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_event_scope_and_version BEFORE INSERT ON tprm_condition_events
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_event_scope_and_version_fn();

CREATE OR REPLACE FUNCTION trg_tprm_condition_event_actor_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF (
    (NEW.actor_type='client_owner' AND (
      NEW.event_type NOT IN ('work_started','evidence_submitted')
      OR NOT EXISTS (
        SELECT 1 FROM tprm_conditions c
        JOIN users u ON u.id=NEW.actor_user_id
        JOIN workspace_members wm ON wm.workspace_id=NEW.workspace_id AND wm.user_id=u.id
        WHERE c.id=NEW.condition_id AND c.workspace_id=NEW.workspace_id
          AND c.supplier_id=NEW.supplier_id AND c.owner_type='client'
          AND c.owner_user_id=u.id AND u.user_type='client' AND u.active=1
          AND wm.role IN ('client_owner','client_admin')
      )
    ))
    OR (NEW.actor_type IN ('consultant','consultancy_manager') AND (
      NEW.event_type NOT IN ('changes_requested','verified','waived')
      OR NOT EXISTS (
        SELECT 1 FROM users u JOIN workspaces w ON w.id=NEW.workspace_id
        WHERE u.id=NEW.actor_user_id AND u.user_type='firm' AND u.active=1
          AND u.firm_id=w.firm_id
          AND (NEW.actor_type!='consultancy_manager' OR u.firm_role IN ('manager','firm_owner'))
      )
    ))
    OR (NEW.event_type='waived' AND NEW.actor_type!='consultancy_manager')
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition action is not authorized for this actor';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_event_actor BEFORE INSERT ON tprm_condition_events
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_event_actor_fn();

CREATE OR REPLACE FUNCTION trg_tprm_condition_event_hash_chain_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF COALESCE(NEW.previous_event_hash,'')<>COALESCE((
    SELECT event_hash FROM tprm_condition_events
    WHERE workspace_id=NEW.workspace_id AND condition_id=NEW.condition_id
    ORDER BY id DESC LIMIT 1
  ),'')
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition event hash chain does not match current history';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_event_hash_chain BEFORE INSERT ON tprm_condition_events
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_event_hash_chain_fn();

CREATE OR REPLACE TRIGGER trg_tprm_condition_event_no_update BEFORE UPDATE ON tprm_condition_events
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM condition events are immutable');

CREATE OR REPLACE TRIGGER trg_tprm_condition_event_no_delete BEFORE DELETE ON tprm_condition_events
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM condition events cannot be deleted');

CREATE OR REPLACE FUNCTION trg_tprm_condition_evidence_scope_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM tprm_condition_events e
    JOIN tprm_conditions c
      ON c.workspace_id=e.workspace_id AND c.supplier_id=e.supplier_id
        AND c.cycle_id=e.cycle_id AND c.id=e.condition_id
    WHERE e.id=NEW.condition_event_id AND e.workspace_id=NEW.workspace_id
      AND e.supplier_id=NEW.supplier_id AND e.cycle_id=NEW.cycle_id
      AND e.condition_id=NEW.condition_id AND e.event_type='evidence_submitted'
      AND e.actor_type='client_owner' AND e.actor_user_id=NEW.uploaded_by
      AND c.owner_type='client' AND c.owner_user_id=NEW.uploaded_by
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition evidence is outside the authorized client submission';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_evidence_scope BEFORE INSERT ON tprm_condition_evidence_links
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_evidence_scope_fn();

CREATE OR REPLACE TRIGGER trg_tprm_condition_evidence_no_update BEFORE UPDATE ON tprm_condition_evidence_links
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM condition evidence links are immutable');

CREATE OR REPLACE TRIGGER trg_tprm_condition_evidence_no_delete BEFORE DELETE ON tprm_condition_evidence_links
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM condition evidence links cannot be deleted');

CREATE OR REPLACE TRIGGER trg_tprm_condition_projection_guard BEFORE UPDATE OF evidence_summary, completion_note, completed_at, completed_by, verified_at, verified_by, waiver_rationale, waiver_expires_at, row_version ON tprm_conditions
  FOR EACH ROW
  WHEN (NEW.status=OLD.status)
  EXECUTE FUNCTION sqlite_raise_abort('TPRM condition fulfilment projection changes only with a governed status event');

