  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM webhook ingress bucket identity is immutable');

CREATE OR REPLACE FUNCTION trg_tprm_review_schedule_closure_negative_decision_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM tprm_client_decisions d
    WHERE d.id=NEW.superseded_by_decision_id
      AND d.workspace_id=NEW.workspace_id
      AND d.supplier_id=NEW.supplier_id
      AND d.decision='do_not_onboard'
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'review schedule closure requires a final negative client decision';
  END IF;
  RETURN NEW;
END;
$fn$;
