  FOR EACH ROW EXECUTE FUNCTION trg_tprm_review_schedule_closure_negative_decision_fn();

CREATE OR REPLACE FUNCTION trg_tprm_review_schedule_closure_client_actor_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM users u
    JOIN workspace_members wm ON wm.user_id=u.id AND wm.workspace_id=NEW.workspace_id
    WHERE u.id=NEW.closed_by AND u.user_type='client' AND u.active=1
      AND wm.role IN ('client_owner','client_admin')
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'review schedule closure requires an authorised active client decision-maker';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_review_schedule_closure_client_actor BEFORE INSERT ON tprm_review_schedule_closures
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_review_schedule_closure_client_actor_fn();

