  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('TPRM review schedule closures cannot be deleted');

CREATE OR REPLACE TRIGGER trg_tprm_relationship_event_hash_required BEFORE INSERT ON tprm_relationship_events
  FOR EACH ROW
  WHEN (NEW.event_hash IS NULL)
  EXECUTE FUNCTION sqlite_raise_abort('TPRM relationship event hash is required');

CREATE OR REPLACE FUNCTION trg_tprm_relationship_event_chain_predecessor_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.previous_event_hash IS DISTINCT FROM (
    SELECT event_hash FROM tprm_relationship_events
    WHERE workspace_id=NEW.workspace_id
      AND relationship_id IS NOT DISTINCT FROM NEW.relationship_id
      AND event_hash IS NOT NULL
    ORDER BY id DESC LIMIT 1
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM relationship event hash-chain predecessor is invalid';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_relationship_event_chain_predecessor BEFORE INSERT ON tprm_relationship_events
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_relationship_event_chain_predecessor_fn();

CREATE OR REPLACE FUNCTION trg_tprm_recommendation_draft_event_chain_predecessor_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.previous_event_hash IS DISTINCT FROM (
    SELECT event_hash FROM tprm_recommendation_draft_events
    WHERE workspace_id=NEW.workspace_id AND draft_id=NEW.draft_id
    ORDER BY id DESC LIMIT 1
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM recommendation draft event hash-chain predecessor is invalid';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_recommendation_draft_event_chain_predecessor BEFORE INSERT ON tprm_recommendation_draft_events
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_recommendation_draft_event_chain_predecessor_fn();

CREATE OR REPLACE FUNCTION trg_tprm_cycle_authority_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.client_decision_authority_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM users u JOIN workspace_members wm ON wm.user_id=u.id AND wm.workspace_id=NEW.workspace_id
        WHERE u.id=NEW.client_decision_authority_id AND u.user_type='client' AND u.active=1
          AND wm.role IN ('client_owner','client_admin')
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM decision authority must be an active client workspace member';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_cycle_authority_insert BEFORE INSERT ON tprm_assessment_cycles
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_cycle_authority_insert_fn();

CREATE OR REPLACE FUNCTION trg_tprm_cycle_authority_update_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF (OLD.client_decision_authority_id IS NOT NULL AND NEW.client_decision_authority_id IS DISTINCT FROM OLD.client_decision_authority_id)
        OR (NEW.client_decision_authority_id IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM users u JOIN workspace_members wm ON wm.user_id=u.id AND wm.workspace_id=NEW.workspace_id
          WHERE u.id=NEW.client_decision_authority_id AND u.user_type='client' AND u.active=1
            AND wm.role IN ('client_owner','client_admin')
        ))
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM decision authority is immutable once assigned and must be an active client workspace member';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_cycle_authority_update BEFORE UPDATE OF client_decision_authority_id ON tprm_assessment_cycles
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_cycle_authority_update_fn();

CREATE OR REPLACE FUNCTION trg_tprm_client_decision_actor_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
        SELECT 1 FROM users u JOIN workspace_members wm ON wm.user_id=u.id AND wm.workspace_id=NEW.workspace_id
        WHERE u.id=NEW.client_actor_user_id AND u.user_type='client' AND u.active=1
          AND wm.role IN ('client_owner','client_admin')
      ) OR EXISTS (
        SELECT 1 FROM tprm_assessment_cycles c
        WHERE c.id=NEW.cycle_id AND c.client_decision_authority_id IS NOT NULL
          AND c.client_decision_authority_id<>NEW.client_actor_user_id
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM onboarding decision requires the assigned active client decision authority';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_client_decision_actor BEFORE INSERT ON tprm_client_decisions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_client_decision_actor_fn();

CREATE OR REPLACE FUNCTION trg_tprm_condition_owner_tenant_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF (
        (NEW.owner_type='client' AND (NEW.owner_user_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM users u JOIN workspace_members wm ON wm.user_id=u.id AND wm.workspace_id=NEW.workspace_id
          WHERE u.id=NEW.owner_user_id AND u.user_type='client' AND u.active=1
            AND wm.role IN ('client_owner','client_admin')
        )))
        OR (NEW.owner_type='consultancy' AND (NEW.owner_user_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM users u JOIN workspaces w ON w.id=NEW.workspace_id
          WHERE u.id=NEW.owner_user_id AND u.user_type='firm' AND u.active=1 AND u.firm_id=w.firm_id
        )))
        OR (NEW.owner_type='third_party' AND NEW.owner_user_id IS NOT NULL)
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition owner does not match the owner type and tenant';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_owner_tenant BEFORE INSERT ON tprm_conditions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_owner_tenant_fn();

CREATE OR REPLACE TRIGGER trg_tprm_condition_status_transition BEFORE UPDATE OF status ON tprm_conditions
  FOR EACH ROW
  WHEN (NOT (
        (OLD.status='open' AND NEW.status IN ('in_progress','waived'))
        OR (OLD.status='in_progress' AND NEW.status IN ('evidence_submitted','waived'))
        OR (OLD.status='evidence_submitted' AND NEW.status IN ('in_progress','verified','waived'))
      ))
  EXECUTE FUNCTION sqlite_raise_abort('invalid governed TPRM condition status transition');

CREATE OR REPLACE FUNCTION trg_tprm_condition_status_requires_event_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.status<>OLD.status AND (
        NEW.row_version<>OLD.row_version+1 OR NOT EXISTS (
          SELECT 1 FROM tprm_condition_events e
          WHERE e.workspace_id=OLD.workspace_id AND e.supplier_id=OLD.supplier_id
            AND e.cycle_id=OLD.cycle_id AND e.condition_id=OLD.id
            AND e.from_status=OLD.status AND e.to_status=NEW.status
            AND e.expected_row_version=OLD.row_version AND e.resulting_row_version=NEW.row_version
          ORDER BY e.id DESC LIMIT 1
        )
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition status requires its append-only governed event';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_status_requires_event BEFORE UPDATE OF status ON tprm_conditions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_status_requires_event_fn();

