  FOR EACH ROW EXECUTE FUNCTION trg_tprm_evidence_release_actor_fn();

CREATE OR REPLACE FUNCTION trg_tprm_evidence_release_ddq_scope_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.source_type='ddq_evidence' AND NOT EXISTS (
        SELECT 1 FROM supplier_ddq_evidence e
        JOIN supplier_ddq_assessments a ON a.id=e.assessment_id
        JOIN tprm_assessment_cycles c ON c.id=NEW.cycle_id
        WHERE e.id=NEW.ddq_evidence_id AND e.workspace_id=NEW.workspace_id
          AND a.workspace_id=NEW.workspace_id AND a.supplier_id=NEW.supplier_id
          AND c.workspace_id=NEW.workspace_id AND c.supplier_id=NEW.supplier_id
          AND c.ddq_assessment_id=a.id
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'released DDQ evidence is outside this governed assessment cycle';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_evidence_release_ddq_scope BEFORE INSERT ON tprm_evidence_releases
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_evidence_release_ddq_scope_fn();

