CREATE OR REPLACE FUNCTION trg_tprm_connector_no_secret_config_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF EXISTS (
        SELECT 1 FROM sqlite_json_tree_keys(NEW.adapter_config_json) j
        WHERE lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) IN (
          'secret','password','passphrase','api_key','apikey','access_token','refresh_token',
          'accesstoken','refreshtoken','authorization','credential','credentials','private_key','privatekey',
          'client_secret','clientsecret','webhook_secret','webhooksecret'
        )
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_secret$'
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_token$'
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_password$'
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_credential$'
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'connector configuration cannot contain secret material; store a secret reference';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_connector_no_secret_config_insert BEFORE INSERT ON tprm_monitoring_connectors
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_connector_no_secret_config_insert_fn();

CREATE OR REPLACE FUNCTION trg_tprm_connector_no_secret_config_update_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF EXISTS (
        SELECT 1 FROM sqlite_json_tree_keys(NEW.adapter_config_json) j
        WHERE lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) IN (
          'secret','password','passphrase','api_key','apikey','access_token','refresh_token',
          'accesstoken','refreshtoken','authorization','credential','credentials','private_key','privatekey',
          'client_secret','clientsecret','webhook_secret','webhooksecret'
        )
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_secret$'
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_token$'
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_password$'
        OR lower(replace(replace(COALESCE(j.key,''),'-','_'),' ','_')) ~ '_credential$'
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'connector configuration cannot contain secret material; store a secret reference';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_connector_no_secret_config_update BEFORE UPDATE OF adapter_config_json ON tprm_monitoring_connectors
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_connector_no_secret_config_update_fn();

