CREATE OR REPLACE FUNCTION trg_tprm_condition_supplier_finding_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.finding_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM supplier_finding_links l
        WHERE l.finding_id=NEW.finding_id AND l.supplier_id=NEW.supplier_id
      )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'TPRM condition finding is not linked to this third party';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_tprm_condition_supplier_finding BEFORE INSERT ON tprm_conditions
  FOR EACH ROW EXECUTE FUNCTION trg_tprm_condition_supplier_finding_fn();

CREATE OR REPLACE TRIGGER trg_evidence_ai_index_identity_immutable BEFORE UPDATE OF workspace_id, evidence_id, source_sha256, source_size_bytes, extractor_version, chunker_version, embedding_provider, embedding_model_requested, embedding_dimensions, vector_format, pipeline_key, external_processing_acknowledged, disclosure_version, authorization_scope, authorized_by, authorized_at, created_at ON evidence_ai_indexes
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('evidence AI index identity and authorization are immutable');

CREATE OR REPLACE TRIGGER trg_evidence_ai_index_transition BEFORE UPDATE OF status ON evidence_ai_indexes
  FOR EACH ROW
  WHEN (NEW.status <> OLD.status AND NOT (
    (OLD.status = 'queued' AND NEW.status IN ('processing','stale'))
    OR (OLD.status = 'processing' AND NEW.status IN ('ready','failed','stale','unsupported'))
    OR (OLD.status = 'ready' AND NEW.status = 'stale')
  ))
  EXECUTE FUNCTION sqlite_raise_abort('invalid evidence AI index status transition');

CREATE OR REPLACE TRIGGER trg_evidence_ai_index_version BEFORE UPDATE ON evidence_ai_indexes
  FOR EACH ROW
  WHEN (NEW.row_version <> OLD.row_version + 1)
  EXECUTE FUNCTION sqlite_raise_abort('evidence AI index update requires the next row version');

CREATE OR REPLACE FUNCTION trg_evidence_ai_index_ready_chunks_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NEW.status = 'ready'
   AND OLD.status <> 'ready'
   AND NEW.chunk_count <> (
     SELECT COUNT(*) FROM evidence_ai_chunks c
     WHERE c.workspace_id = NEW.workspace_id
       AND c.evidence_id = NEW.evidence_id
       AND c.index_id = NEW.id
   )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'evidence AI index chunk count is incomplete';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_evidence_ai_index_ready_chunks BEFORE UPDATE OF status ON evidence_ai_indexes
  FOR EACH ROW EXECUTE FUNCTION trg_evidence_ai_index_ready_chunks_fn();

CREATE OR REPLACE FUNCTION trg_evidence_ai_chunk_processing_parent_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM evidence_ai_indexes i
    WHERE i.workspace_id = NEW.workspace_id
      AND i.evidence_id = NEW.evidence_id
      AND i.id = NEW.index_id
      AND i.status = 'processing'
  )
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'evidence AI chunks require a processing parent index';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_evidence_ai_chunk_processing_parent BEFORE INSERT ON evidence_ai_chunks
  FOR EACH ROW EXECUTE FUNCTION trg_evidence_ai_chunk_processing_parent_fn();

CREATE OR REPLACE TRIGGER trg_evidence_ai_chunk_no_update BEFORE UPDATE ON evidence_ai_chunks
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('evidence AI chunks are immutable');

CREATE OR REPLACE FUNCTION trg_evidence_ai_source_stale_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  UPDATE evidence_ai_indexes
       SET status = 'stale',
           lease_expires_at = NULL,
           stale_at = utc_now_text(),
           last_error_code = COALESCE(last_error_code,'evidence_source_changed'),
           last_error_redacted = COALESCE(last_error_redacted,
             'The evidence source changed or was superseded; this derived index is no longer queryable.'),
           updated_at = utc_now_text(),
           row_version = row_version + 1
     WHERE workspace_id = OLD.workspace_id
       AND evidence_id = OLD.id
       AND status IN ('queued','processing','ready');
  RETURN NULL;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_evidence_ai_source_stale AFTER UPDATE OF workspace_id, stored_path, sha256, size_bytes, superseded_at ON evidence
  FOR EACH ROW
  WHEN (NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
    OR NEW.stored_path IS DISTINCT FROM OLD.stored_path
    OR NEW.sha256 IS DISTINCT FROM OLD.sha256
    OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes
    OR NEW.superseded_at IS DISTINCT FROM OLD.superseded_at)
  EXECUTE FUNCTION trg_evidence_ai_source_stale_fn();

CREATE OR REPLACE FUNCTION control_record_version_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  NEW.record_version := OLD.record_version + 1;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER control_record_version BEFORE UPDATE ON control_instances
  FOR EACH ROW WHEN (NEW.record_version = OLD.record_version)
  EXECUTE FUNCTION control_record_version_fn();

CREATE OR REPLACE FUNCTION client_request_release_on_insert_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  NEW.released_at := utc_now_text();
  NEW.released_by := NEW.created_by;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER client_request_release_on_insert BEFORE INSERT ON client_requests
  FOR EACH ROW WHEN (NEW.assignee_id IS NOT NULL AND NEW.released_at IS NULL)
  EXECUTE FUNCTION client_request_release_on_insert_fn();

CREATE OR REPLACE FUNCTION client_request_release_on_assignment_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  NEW.released_at := utc_now_text();
  NEW.released_by := NEW.created_by;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER client_request_release_on_assignment BEFORE UPDATE OF assignee_id ON client_requests
  FOR EACH ROW WHEN (NEW.assignee_id IS NOT NULL AND NEW.released_at IS NULL)
  EXECUTE FUNCTION client_request_release_on_assignment_fn();

CREATE OR REPLACE FUNCTION trg_assessment_review_event_scope_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM requirements r JOIN frameworks f ON f.id=r.framework_id
    WHERE r.id=NEW.requirement_id AND f.code=NEW.framework_code)
   OR (NEW.request_event_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM assessment_review_events e
    WHERE e.id=NEW.request_event_id AND e.workspace_id=NEW.workspace_id AND e.requirement_id=NEW.requirement_id AND e.action='request'))
  THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'assessment review source does not match';
  END IF;
  RETURN NEW;
END;
$fn$;
CREATE OR REPLACE TRIGGER trg_assessment_review_event_scope BEFORE INSERT ON assessment_review_events
  FOR EACH ROW EXECUTE FUNCTION trg_assessment_review_event_scope_fn();

CREATE OR REPLACE TRIGGER trg_assessment_review_events_no_update BEFORE UPDATE ON assessment_review_events
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('assessment review history is immutable');

CREATE OR REPLACE TRIGGER trg_assessment_review_events_no_delete BEFORE DELETE ON assessment_review_events
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('assessment review history is immutable');

CREATE OR REPLACE TRIGGER risk_assessment_records_sealed_update BEFORE UPDATE ON risk_assessment_records
  FOR EACH ROW
  EXECUTE FUNCTION sqlite_raise_abort('A recorded risk assessment cannot be changed.');
